insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 1, 'In this module''s grade curve, what is the removal efficiency of a droplet whose diameter equals the device''s own cut size?', '["One half only at the declared sharpness of 3, and it drifts away from that value at the derived sharpness of 2.", "It depends on the device, because a hydrocyclone and a media bed place their half points at different reduced sizes.", "Exactly one half, 0.500000000000, at every sharpness the module accepts.", "Whatever the integration over the droplet distribution in front of the device happens to return for that one bin."]'::jsonb, 2, 'The reduced form is r to the m over one plus r to the m. At a reduced size of one the numerator and the denominator are equal whatever m is, so the half point is fixed by what a cut size MEANS rather than by any tuning.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 2, 'What is the reduced size this module writes its grade curve in?', '["The droplet diameter divided by the device''s own cut size.", "The droplet diameter divided by the median diameter of the water arriving at that device.", "The droplet volume divided by the coarsest reported bin.", "The droplet diameter divided by the 20 micron reference droplet the filter coefficient is declared at."]'::jsonb, 0, 'Writing the curve in that ratio is what lets one family serve every device here. A basin, a liner, a cell and a bed produce four different cut sizes by four different arguments, and each one then sets its own horizontal scale.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 3, 'Two devices have the same cut size, one at a sharpness of 3 and one at a sharpness of 2. What does each remove at four times that cut size?', '["94.117647 percent at the sharpness of 3 and 98.461538 percent at the sharpness of 2, because a lower exponent is the steeper climb away from the half point.", "98.461538 percent at both of them, because the two curves are pinned together at the cut size and again at four times it.", "5.882353 percent at the sharpness of 3 and 1.538462 percent at the sharpness of 2, which is the coarse end of the reduced curve.", "98.461538 percent at the sharpness of 3 and 94.117647 percent at the sharpness of 2."]'::jsonb, 3, 'The sharper curve separates better on both sides of the cut at once. It takes more of the coarse oil and it also passes more of the fine oil, and the two statements are one statement about selectivity.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 4, 'At a quarter of the cut size the sharpness of 2 removes 5.882353 percent and the sharpness of 3 removes 1.538462 percent. What does that pair of figures show?', '["That the two curves cross somewhere below the cut size, which is the reason this module prints the sharpness beside every cut size it reports.", "That the blunter curve picks up more of the fine oil, which is what the sharper curve gives away for its performance on the coarse side.", "That the sharper curve reaches the fine tail first, since 1.538462 percent is the figure carried by the sharpness of 2.", "That the sharpness moves where the half point sits, putting it below the cut size for the blunter of the two curves."]'::jsonb, 1, 'Read this row beside the row at four times the cut size. A sharp device draws a cleaner line between what it catches and what it passes, and which side of that line is worth more depends entirely on the distribution in front of it.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 5, 'Which sharpness does this module use for which devices?', '["3 for the gravity devices and the hydrocyclone, and 2 for flotation and the media bed.", "2 for the gravity devices and the cyclone, and 3 for flotation and the bed.", "3 for every device here, with the 2 reserved for the curve the train integrates after its last stage has run.", "3 for the hydrocyclone alone, since it is the one device whose curve an oracle marches, and 2 for everything else."]'::jsonb, 0, 'The two values also have different standing. The 3 is DECLARED in the frozen constants as `defaultSharpness`. The 2 falls out of interception capture rather than from anybody choosing it.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 6, 'Why is the sharpness of the flotation cell and the media bed DERIVED rather than chosen?', '["Both were fitted against the published cell and bed rows in the golden file, and a sharpness of 2 is what that fit returned.", "Both capture by interception, whose rate goes as the square of the droplet diameter, so the survival is an exponential in the square of the reduced size, which has the same half point and the same leading power as the family at m equal to 2.", "Both report a cut finer than the gravity devices do, and this module lowers the sharpness whenever a cut falls under the reference droplet.", "A sharpness of 2 is what the reduced efficiency family falls back to whenever a caller supplies no sharpness of their own."]'::jsonb, 1, 'Change the capture mechanism and the exponent changes with it. That is what makes it a derivation, and it is why the module can say where the exponent came from rather than only what it is.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 7, 'What is the sharpness never allowed to do here?', '["Fall below 2, because this module refuses a grade curve blunter than the interception one.", "Differ between two stages of one train, because the quadrature integrates a single curve across all of them.", "Rise above the declared 3, because that is the sharpest curve this repository carries any source for.", "Move the cut size, because the half point is nailed at a reduced size of one."]'::jsonb, 3, 'The two columns of the reduced curve describe two devices with identical cut sizes and different selectivity. A sharpness that moved the half point would be describing a different cut size instead of a different curve.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 8, 'One device is applied to this water at a cut size of 12 micron. What does the module report for the removal and for the outlet droplet median?', '["78.263077 percent removed, with an outlet median of 12 micron, because the cut size becomes the median of the water that survives.", "60.477315 percent removed, with a median of 14.126621 micron.", "78.263077 percent removed, with an outlet median of 10.953502 micron.", "92.922276 percent removed, with an outlet median of 7.691060 micron, since the removal is read against the inlet median."]'::jsonb, 2, 'The two figures answer different questions. The removal is what this vessel took out. The median is what the next vessel will be asked to work on, and it has fallen because the device took the coarse oil preferentially.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 9, 'The module reports a surviving volume of 0.217369227363 beside that removal. What is that number for?', '["It is the share of the inlet oil this device never reached at all, because those droplets fell outside the droplet grid that was reported back.", "It is the divisor the outlet bins are renormalised by, so that the oil left can be described as a distribution in its own right.", "It is the oil carried away in the reject stream the device sends off with its froth or its underflow.", "It is the grade efficiency at the reported cut size, which is what the removal integral is normalised against."]'::jsonb, 1, 'The removal and the surviving volume are two views of one sum and they account for all of the oil between them. Renormalising by that divisor is what turns what survived into an inlet for the next stage.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 10, 'A device on this water is tightened from a cut of 30 micron to a cut of 2 micron. What happens to the outlet droplet median?', '["It falls, from 16.943389 micron to 4.880416 micron.", "It rises, from 4.880416 micron to 16.943389 micron, because the coarse droplets are the ones a tighter device leaves behind.", "It holds at the inlet median throughout, because taking oil out does not change the shape of the oil that is left.", "It falls to 2 micron, because a device cutting there leaves nothing coarser than its own cut size in the water."]'::jsonb, 0, 'A device removes the droplets it is good at, and those are the coarse ones, so the water leaving is always finer than the water that arrived. Tighten the cut and more of that coarse oil goes.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 11, 'A device cutting at 0.001 micron on this water removes 99.999999999904 percent and leaves a surviving volume of 9.618e-13. What does the module report?', '["A refusal naming the cut size it was handed, because a surviving volume that small is outside anything the grid can describe.", "A concentration and an outlet median of 0.001 micron, since every droplet coarser than that has been taken out.", "A removal rounded up to 100.000000 percent, with the outlet distribution reported back as an empty set of bins.", "A concentration, with `outletNormalised` no, no outlet droplet median at all, and a warning that what is left is numerical dust."]'::jsonb, 3, 'In the engine''s own words: this device leaves 9.62e-13 of the oil volume behind: what is left is numerical dust and no outlet droplet median is reported for it. Renormalising a number that small would produce a median with a confident look and no content.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 12, 'How is a device removal computed in this module?', '["The grade efficiency is evaluated once at the inlet median diameter and that one figure is applied to the whole of the oil volume arriving.", "The cut size is compared with the inlet median and a removal is read from a curve indexed by those two.", "Each bin''s volume fraction is multiplied by the grade efficiency at that bin''s diameter, and the products are summed.", "A removal is looked up for the device type and then scaled by the ratio of the cut size to the inlet median."]'::jsonb, 2, 'Take the complement bin by bin instead of the product and you have the volume that survives, which becomes the outlet once it is renormalised. One quadrature yields both of them.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 13, 'Why does this module carry the outlet distribution forward as well as the removal?', '["Because the outlet median is what the next stage''s reported cut size is rescaled against before its quadrature can run.", "Because the next device faces that water rather than the inlet water, and it performs worse on it than its own cut size alone would suggest.", "Because the renormalisation is what restores the truncated tail the droplet grid dropped at the inlet.", "Because the concentration alone cannot be carried between stages, since removal is reported as a fraction of the oil."]'::jsonb, 1, 'That coupling is the whole point of a train, and it is exactly what a table of fixed removal efficiencies throws away.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 14, 'What can a fixed removal efficiency for a device not do?', '["Say what the water leaving looks like, so it cannot say what the next device will do with it.", "Reproduce the removal of one device on one water, which is the single case such a figure is fitted for.", "Move at all when the vessel geometry changes, although it does respond when the water temperature does.", "Respond to the plan area of a vessel, though it tracks the median arriving."]'::jsonb, 0, 'The same device on finer water performs worse, and a quoted percentage cannot know that because it never knew what arrived. Every figure in this course is a cut size against a distribution instead.'),
  ('producedwater', 'intermediate', 'module', 'm01-grade-efficiency', 15, 'What is the standing of the sharpness of 3 in this module?', '["DERIVED, since it follows directly from the same settling balance that the gravity devices invert in order to arrive at their own cut size.", "A CALIBRATION, chosen so that a basin cuts in the range API 421 vessels are customarily credited with.", "HELD FOR LITERATURE, which is why the module states an absence in its place rather than a value.", "DECLARED, which is to say chosen and exported in one frozen object, with no publication here to check it against."]'::jsonb, 3, 'The module''s own comment says that pinning such a number is all any gate can do, and a pin is not a validation. What a pin buys is that moving the value becomes a reviewed act rather than a silent one.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 1, 'Droplets entering a liner are spread across its cross section BY AREA. What follows for the droplet in the middle of the distribution?', '["It enters at half of the bore radius, since equal radii carry equal volumes of water down the tube.", "It enters at the half-area radius, 0.707106781187 of the bore radius, because half of the flow area sits inside that circle.", "It enters at the wall, because the tangential inlet delivers the whole feed against the outside of the liner.", "It enters at the oil core radius, which is where the module places the median of any feed it is given."]'::jsonb, 1, 'Equal areas of the inlet carry equal volumes of water, so equal areas carry equal volumes of oil. That radius is a criterion rather than a stored constant, and the module never carries it as a choice.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 2, 'How does this module get the residence time of one liner?', '["The liner length divided by the tangential velocity the inlet slot develops at that flow.", "The bank volume divided by the total flow through the vessel, since every liner in a bank is fed in parallel from one common header.", "The travel to the oil core divided by the rise velocity the same droplet would have under gravity alone.", "The liner volume divided by the flow going through that one liner, which on the KOKORI bank is 0.000673478925 m3 over 0.000690049023 m3/s."]'::jsonb, 3, 'Nothing else enters it. The result is 0.975987 s, which is just under a second, and everything a de-oiling liner does it does inside that.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 3, 'What distance does the module take the cut droplet to cross, and what fixes it?', '["The gap from the half-area radius in to the oil core, which on the 0.035 m bore is 0.003624368671 m.", "The full bore radius, since a droplet must reach the axis of the liner to be taken off in the overflow.", "The liner length of 0.7 m, which is the path the water follows as it spirals down the tube.", "The difference between the liner radius and the half-area radius, which is the outer half of the flow area."]'::jsonb, 0, 'The travel is a radial distance, so the two radii that bound it are what set it. The half-area radius is a criterion and the core position is DECLARED, which makes one end of this gap a modelling choice.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 4, 'A liner is lengthened from 0.5 m to 1 m at a fixed bore. What happens to the travel and to the cut size?', '["The travel and the cut both fall, because a longer tube brings the oil core closer to the wall along its length.", "Neither one moves, because length reaches the field and the gap alike.", "The travel does not move at all, and the cut goes from 5.242462 micron to 3.706980 micron.", "The travel rises with the length and the cut rises with it, from 3.706980 micron to 5.242462 micron."]'::jsonb, 2, 'Lengthening a tube does not change its radius, so the radial gap is untouched. What a longer liner buys is residence time at the same travel, and the cut gets finer with it.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 5, 'A designer widens the liner bore at a fixed length and a fixed flow per liner. Which way does the reported cut size go?', '["Coarser, because a wider bore puts the wall further from the axis and the droplet has more to cross.", "Coarser at first and then finer, because the residence gain only overtakes the travel cost past the declared bore.", "It does not move, because the bore reaches the cut only through the field, and the field is fixed by the turndown.", "Finer, and it goes as one over the square root of the bore."]'::jsonb, 3, 'The residence goes as the SQUARE of the bore, because the liner volume does, while the travel from the half-area radius to the core goes only as the bore itself. The residence wins by exactly one power.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 6, 'Why does the bore win for the residence rather than for the travel?', '["Because the field rises with the bore as well, and the field and the residence together outweigh the extra distance.", "Because the liner volume carries the bore squared and so the residence does, while the radial gap carries only one power of it.", "Because the migration velocity rises with the bore, so the droplet crosses a longer gap at a higher speed.", "Because a wider liner is held to run at a lower turndown, and a lower turndown buys a longer residence at the very same flow."]'::jsonb, 1, 'Both effects are real and they pull opposite ways. Counting the powers is what settles it, and it settles it the same way at every bore rather than only at the sampled ones.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 7, 'Across the bore sweep at a fixed length the field column reads 1322.687929 g on every row. Why?', '["Because no dimension of the liner enters the field, which is set by the turndown alone.", "Because the sweep was run at the ceiling, where the reported field cannot rise any further whatever the bore is.", "Because the bore raises the tangential velocity and lowers the radius by the same factor, so the field cancels.", "Because the field is DECLARED at 1000 g and the module scales it only with the liner count of the bank."]'::jsonb, 0, 'The turndown is the flow through one liner over its design flow, and neither of those carries a bore. That is what makes the race in this sweep a race between the residence and the travel and nothing else.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 8, 'The digest prints a derived column beside the bore sweep, the cut size multiplied by the square root of the bore. What does it read?', '["0.828906 on the declared bore alone, and it drifts away from that figure at the two extremes of the span.", "1.000000 on every row, because the column is normalised against the module''s own declared bore of 0.035 m.", "0.828906 on every one of the five rows, across a tenfold span of bore from 0.01 to 0.1 m.", "It rises steadily with the bore, so the exponent is the stronger one."]'::jsonb, 2, 'A derived column that holds still is a claim about the FORM of a relationship and it can be read by eye. A constant there says the cut goes as one over the root of the bore exactly.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 9, 'Is there a bore at which a wider liner starts cutting coarser again?', '["Yes, and it sits just above the widest bore in the sweep, which is why the table stops at 0.1 m.", "No, and that is a statement about the law rather than about the sampled rows, because one over a square root has no turning point.", "Yes, at the bore where the cut droplet leaves the creeping flow band and the migration velocity stops rising.", "The module cannot say either way, because the sweep it printed covers only a tenfold span of bore and a turn could easily lie outside it."]'::jsonb, 1, 'A sweep can only ever report the rows it walked. Here the exponent is exact and the derived column proves it, so the direction is settled for every bore and not only for the five that were printed.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 10, 'The oil core is moved from 0.5 of the liner radius to 0.65. What does the module report?', '["A travel of 0.006249368671 m and a cut of 5.817992 micron, since the gap widens as the core moves out.", "The same travel and the same cut, because the core position is a reporting convention rather than an input.", "A refusal, because a core past half of the radius leaves the median droplet with nothing to cross.", "A travel of 0.000999368671 m and a cut of 2.326580 micron."]'::jsonb, 3, 'Moving the core outward shortens the gap the median droplet has to make, so the liner appears to catch finer oil. The core position is DECLARED and has no published source here, so a reader moving it is moving a modelling assumption.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 11, 'A caller asks for an oil core at 0.75 of the liner radius and the module REFUSES. What does the refusal rest on?', '["That the core must sit inside the half-area radius or the median droplet starts inside it and has nothing to cross.", "That the customary core fraction for a de-oiling liner lies between 0 and 0.7071 in the published literature.", "That a core that wide leaves too little annulus for the clean water to leave through at the design flow.", "That the cut size would fall below the creeping flow band, where the migration velocity is no longer honest."]'::jsonb, 0, 'That is a criterion rather than a range check somebody chose. Past one over the root of two the question the model answers has stopped making sense, and the refusal quotes the reason rather than a limit.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 12, 'How is the cut size of a liner defined in this module?', '["As the droplet at which the marched capture fraction first exceeds the oracle''s own reported figure.", "As the droplet whose rise under gravity equals the surface loading.", "As the droplet whose radial migration just crosses the travel in the residence time.", "As the droplet where the declared sharpness of 3 gives one half."]'::jsonb, 2, 'On the KOKORI bank the droplet has 0.003624368671 m to cross and 0.003713541683 m/s to do it in, and those two divide into the residence of 0.975987 s. The grade curve is what the train integrates afterwards and it plays no part in finding the cut.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 13, 'The KOKORI bank reports a shear penalty of 1.000000. What does that tell a reader?', '["That the bank is running exactly at its design flow, which is the only turndown at which no penalty applies.", "That the ideal cut and the reported cut are the same number here, 4.430689 and 4.430689.", "That the penalty was suppressed because the reported field had already reached its ceiling on this bank.", "That the liner applies no shear, so the inlet reaches it untouched."]'::jsonb, 1, 'The reported cut is the ideal cut with a penalty multiplied onto it, and the penalty is one until the bank is pushed past its envelope. This bank sits at a turndown of 1.150082, which is inside it.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 14, 'The `cutBasis` string on every hydrocyclone return names three things the model leaves out. Which three?', '["Re-entrainment, the reject split and the shear the liner itself applies.", "The fouling of the liner, the pressure drop across it and the reject split it operates at.", "Re-entrainment, the droplet coalescence inside the core and the backwash the bank needs.", "The inlet slot geometry, the swirl decay along the tube and the oil recovery balance."]'::jsonb, 0, 'The same string adds that field de-oilers are customarily credited with a coarser cut than this. A reader who takes the cut size and leaves the basis behind has taken half of what the engine returned.'),
  ('producedwater', 'intermediate', 'module', 'm02-the-hydrocyclone', 15, 'Why does the module report a Reynolds number of 0.030870 beside the KOKORI liner cut?', '["So a reader can convert that migration velocity into the equivalent rise velocity the same droplet would have had under gravity alone.", "Because the Reynolds number is what the reported field is divided by to give the shear penalty.", "Because the oracle needs it in order to march droplets of that diameter from starting radii spread by area.", "So a reader can see that the migration velocity was computed where the creeping flow law behind it is honest."]'::jsonb, 3, 'Every device in this module reports the Reynolds number of its OWN cut droplet and warns the same way. A cut that fell outside the band would say so on the same return instead of arriving quietly.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 1, 'Turndown is the single figure saying how hard a bank is being run. What is it a ratio of?', '["The bank flow divided by the flow the whole vessel was ordered to pass at its design point.", "The reported field over the 1000 g a liner gives at its rated flow.", "The flow one liner is actually carrying divided by the flow one liner is rated at.", "The ratio of the liner count installed to the liner count the module says the flow wants."]'::jsonb, 2, 'Split 75000 bwpd across 200 liners and each carries 0.000690049023 m3/s against a rated 0.0006, which is 1.150082. It is the single number saying how hard the bank is being run, and the field and the residence both follow from it.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 2, 'How does the reported field respond to the turndown inside the operating envelope?', '["It goes as the square of it, because the field goes as the square of the tangential velocity and that goes with the flow.", "It goes linearly with it, because the tangential velocity is what the inlet slot converts the flow into.", "It goes as the square root of it, because the swirl decays along the tube as the flow rises.", "It does not respond at all inside the envelope, where the module holds the field at its declared 1000 g."]'::jsonb, 0, 'That is a strong dependence and it is exactly why a designer is tempted to buy fewer liners. Halve the bank and each remaining liner sees twice the flow, which looks like four times the field.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 3, 'Where does the module put the ceiling on the reported field, and why is it there?', '["At 1000 g, because that is the field one liner is DECLARED to develop and the module will not report more.", "At 1690.000000 g, because past 1.3 times design the inlet slot chokes and the extra energy goes into pressure drop rather than rotation.", "At 1690.000000 g, because above that figure the cut droplet would leave the creeping flow band that the radial migration law behind it is stated to.", "At 1690.000000 g, because that is the highest field any published row in the golden file carries."]'::jsonb, 1, 'Above the top of the envelope the field column in the sweep sits at exactly that number and stops. A ceiling on its own would only make the cut stop improving.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 4, 'A bank of 120 liners on the KOKORI flow reports an ideal cut of 5.060355 micron and a reported cut of 6.144662 micron. What sits between them?', '["A correction for the field having been capped, which restores the cut the uncapped field would have given.", "The Reynolds number of the cut droplet, which the module divides the ideal cut by outside the creeping band.", "The turndown of 1.916803, which multiplies the ideal cut once the bank passes twice its design flow.", "A shear penalty of 1.214275, which is the root of the overload applied as a multiplier on the ideal cut."]'::jsonb, 3, 'A liner pushed past its slot rating accelerates water harder than the design intends, and shear breaks oil droplets finer than they arrived. Finer droplets are harder for any device to catch, so the same liner on the same water reports a coarser cut when it is overdriven.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 5, 'Where in the swept table does the finest cut size sit?', '["At 177 liners, 4.168146 micron at a turndown of 1.299527.", "At 120 liners, 6.144662 micron, which is the smallest bank the sweep printed.", "At 230 liners, 4.751385 micron, where the bank runs closest to its design point.", "At 600 liners, 7.674178 micron, where the field column reaches its highest value in the sweep."]'::jsonb, 0, 'It is NOT the smallest bank. A designer reading the cut column from the top down sees it improving as liners come out, right up to the row where it stops and reverses.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 6, 'By how much is the smallest bank in that sweep worse than the best one?', '["1.299527 times, which is the turndown at the row carrying the finest cut in the sweep.", "1.214275 times, which is the shear penalty the smallest bank in the sweep carries.", "1.474196 times, which is 6.144662 micron against 4.168146 micron.", "1.916803 times, which is the turndown the smallest bank in the sweep is running at."]'::jsonb, 2, 'The figure is derived, the two cut sizes divided. Taking liners out of the best bank in that table buys a cut half again as coarse, which is the whole engineering content of it.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 7, 'Two separate mechanisms put the turn in that sweep. Which two?', '["The ceiling on the field and the refusal past twice design flow.", "The starved warning at the top of the table and the overload warning at the bottom.", "The square law on the field and the square root law on the residence time.", "The ceiling on the field and the inlet shear penalty on the cut."]'::jsonb, 3, 'A ceiling alone would flatten the curve and leave the cut merely not improving. A ceiling plus a penalty turns it over, so the cut gets WORSE from the envelope onward in direct proportion to the overload.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 8, 'What does the module report at the top of the sweep, 600 liners on the KOKORI flow?', '["A refusal, because a bank that far below its design flow is outside what the module will describe.", "A turndown of 0.383361, a field of 146.965325 g, a cut of 7.674178 micron and a starved warning.", "A turndown of 0.383361 with no warning, since the module only warns above its operating envelope.", "A cut of 4.168146 micron, because the longest residence in the table sits on that row."]'::jsonb, 1, 'The column is worse at both ends and best in between, and neither end is visible from a single design point. That is the argument for sweeping an input rather than running one case.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 9, 'A caller puts the KOKORI flow through 115 liners and the module REFUSES. What does the refusal hand back?', '["The cut size the bank would have reported had the module been willing to extrapolate.", "The largest flow those 115 liners could take.", "The liner count that would run this flow at its design point, 231 liners.", "The shear penalty the bank would carry, so a caller can apply it to the ideal cut themselves."]'::jsonb, 2, 'The sentence also carries the count it was given, the flow each liner is carrying, the turndown that produces, the design flow it was judged against and the reason the limit exists. A user who typed a number far too small is told what a sensible one would be.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 10, 'A one liner bank on the same flow refuses and names the same 231 liners. Why the same number?', '["Because that count is a property of the flow and the rated flow per liner rather than of the bad input.", "Because the module reports the nearest liner count it has a published row for in the golden file.", "Because 231 is the count at which the reported field would reach its ceiling on this particular flow.", "Because the refusal quotes the bank the caller last asked about rather than recomputing it."]'::jsonb, 0, 'The flow divided by the design flow per liner answers the question whatever the caller typed. That is what makes it a refusal that hands back a design instead of a bare error.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 11, 'What is the difference between the starved warning and the overloaded warning?', '["Starved is a warning and overloaded is a refusal, since the module will not report a penalised cut size.", "Starved applies below the design flow and overloaded above it, and both leave the reported cut untouched.", "Starved means the reported cut is optimistic and overloaded means it is conservative, at the same field.", "Starved is advice about how to run the bank you have, and overloaded says the number beside it is getting worse and the bank is too small."]'::jsonb, 3, 'One fix is operational and the other is capital. A reader who can tell those apart can tell an operating decision from a purchase order, which is the whole point of separating them.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 12, 'A bank runs at 0.328595 of its design flow. What does the module do?', '["It refuses, since 0.328595 is under the declared 0.5.", "It ANSWERS, with a cut of 8.289060 micron and a warning telling the operator to shut liners in.", "It answers with the cut it would give at the bottom of the envelope, since the field is clamped there.", "It answers with no warning, since a starved bank is honest."]'::jsonb, 1, 'In the engine''s own words the warning reads that below about 0.5 the centrifugal field collapses with the square of the flow and the cut size degrades fast, so shut liners in rather than running them all starved.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 13, 'The published liner rows carry an oracle capture fraction of 0.500455 at the reported cut. What makes that figure worth anything?', '["It comes from a different method, droplets fired from starting radii spread by area and marched, against the one half a cut size is DEFINED as.", "It comes from precisely the same march the engine itself runs, recorded back into the golden file so that any later rerun can be compared against it.", "It is the grade efficiency of the declared sharpness of 3 evaluated at a reduced size of exactly one.", "It is the fraction of the published rows whose cut size the engine reproduces to every digit printed."]'::jsonb, 0, 'An agreement between two routes that share no arithmetic is evidence. An agreement between two copies of one routine is bookkeeping, and telling those apart is the habit this course is built on.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 14, 'What is happening at the 230 liner row of the sweep?', '["The bank is at the top of its envelope, which is where the reported field stops rising.", "The bank is at the bottom of its envelope, which is where the starved warning first appears.", "The bank is at its design point, a turndown of 1.000071 and a field of 1000.142101 g.", "The bank is at the finest cut in the sweep, since the field has reached its ceiling there."]'::jsonb, 2, 'The declared design flow of 0.0006 m3/s per liner and the declared 1000 g meet on that row, which is why both figures sit a hair above their round values rather than on them.'),
  ('producedwater', 'intermediate', 'module', 'm03-the-operating-envelope', 15, 'What is the portable habit this sweep is meant to teach?', '["Design at the centre of the declared envelope, since the edges of it carry warnings in either direction.", "Prefer the smallest equipment that still answers, because the module refuses anything genuinely unsafe.", "Trust a reported optimum when the model prints a warning column, since the warnings police the extremes.", "Sweep the input a user is most tempted to change and read the DIRECTION of the answer rather than any single value."]'::jsonb, 3, 'A model whose answer improves without limit as an input is pushed has no limit in it, and a studio telling a designer to buy less equipment for a better answer is worse than no studio. This one has a limit and the table shows where.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 1, 'Why is a flotation cut size a rate question rather than a settling question?', '["Because the bubbles rise faster than any droplet settles, so the settling term drops out of the balance.", "Because the cell is stirred, which destroys the quiescent layer a settling calculation would need.", "Because the froth is skimmed continuously, so no droplet is ever given a fixed distance to travel.", "Because the oil leaves attached to gas, so what matters is how likely a droplet is to meet a bubble and stick in the time the water is in the cell."]'::jsonb, 3, 'There is no distance a droplet has to cross in this device. The cut is the droplet the cell removes half of in its residence time, and that is a completely different shape of argument from a basin or a liner.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 2, 'Gas is fed to the KOKORI cells at 0.25 times the water flow. What does the return report?', '["0.172512255781 m3/s to each cell, which is the bank total divided among the five of them.", "0.034502451156 m3/s to each cell and 0.172512255781 m3/s in all.", "0.034502451156 m3/s in all, shared between the cells according to their volumes.", "0.008050571936 m3/s to each cell, which is the gas rate the flux is formed from."]'::jsonb, 1, 'The ratio is applied to EACH cell, so the two figures are different quantities. A reader comparing two arrangements needs to know which one a menu setting moved, and four cells at a ratio use four times the gas of one.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 3, 'How does the module turn a cell volume into the area the gas rises through?', '["It takes the square of the cube root of the volume, since the module assumes a cubic cell.", "It divides the volume by the residence time and then by the superficial gas velocity.", "It divides the volume by the cell depth, so 12 m3 at a depth of 2.8 m gives 4.285714 m2.", "It reads the plan area directly, because a cell is specified here by its area and its depth."]'::jsonb, 2, 'Bubbles rise through an AREA and a cell is specified by a volume, so something has to bridge the two. The superficial gas velocity is then the gas per cell over that plan area, 0.008050571936 m/s.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 4, 'A cell of fixed volume is made deeper, from 1.5 m to 6 m. What happens to the cut size?', '["It gets finer, from 32.427302 micron to 16.213651 micron.", "It gets coarser, from 16.213651 micron to 32.427302 micron, because a deeper cell is a longer rise.", "It does not move, because the residence time is the volume over the flow and the volume has not changed.", "It gets finer only until the holdup passes the declared swarm limit, and then it turns back."]'::jsonb, 0, 'A deeper cell at the same volume is a NARROWER cell, so the same gas rises through less plan area, the flux is higher and the cut is finer. Nothing about that is visible from a residence time argument, which is why depth had to become an input.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 5, 'A 400 micron bubble in this water rises at 0.055485861717 m/s, which is a Reynolds number of 41.641016. What does the module use to get that velocity?', '["Stokes law with a warning attached to the return, since this module states that law only as far as a Reynolds number of 1.", "The full drag balance, because at a Reynolds number in the tens Stokes law is no longer the settling law.", "Stokes law left uncorrected, because a rising gas bubble in water is always inside the creeping flow band.", "A declared rise velocity for the default bubble, scaled by the ratio of the bubble diameters."]'::jsonb, 1, 'The module did not apply the wrong law and attach a warning. It used the method that is honest at these conditions, and it reports the Reynolds number so a reader can see which regime the bubble is in.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 6, 'How does the module compute the gas holdup of the swarm?', '["The gas rate per cell divided by the cell volume, which is the gas fraction of that volume.", "The bubble rise velocity divided by the superficial gas velocity, which makes a quickly rising bubble a high holdup.", "The total gas to the bank divided by the water flow, which is the declared gas to water ratio.", "The superficial gas velocity divided by the bubble rise velocity, which on the KOKORI cell is 0.145092311579."]'::jsonb, 3, 'It is bookkeeping. Gas arrives at the bottom at a flux and leaves the top at the bubble rise velocity, so the amount sitting in the cell at any moment is the ratio of the two.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 7, 'At a gas to water ratio of 1.5 the holdup is 0.870553869473, past the declared 0.2, and the module still reports a cut of 9.689510 micron. What does the warning mean?', '["That the model behind that figure is outside the conditions it was built for, so the number should be read as an extrapolation.", "That the figure has been clamped at the swarm limit, so the true cut is finer than the one reported.", "That the cut size is withheld and the concentration alone is returned for that arrangement.", "That the cell is being fed more gas than it can possibly disengage at the surface, so the cut size reported beside the warning is a conservative one."]'::jsonb, 0, 'A warning withholds nothing. It reports the answer, names the quantity, names the threshold and leaves the judgement with the reader who knows what cell was actually built. Past that holdup the bubbles meet each other rather than the water.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 8, 'What does the interception rate constant of 2830279.196411133744 per second per square metre of droplet diameter tell a reader about the capture law?', '["That capture goes as the square of the bubble diameter, since the bubble is the collector here.", "That capture goes linearly with the droplet diameter, with the square being an artefact of the area units.", "That capture goes as the SQUARE of the droplet diameter, which is what the units of the constant carry.", "That the constant is a calibration, since no rate with units like that could be derived from geometry."]'::jsonb, 2, 'A droplet is caught when it comes within its own radius of a bubble, so the efficiency of the encounter carries the droplet diameter squared. That same square is what fixes this device''s sharpness at 2.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 9, 'Where does the cut size of a flotation cell sit on the decay curve?', '["Where the rate multiplied by the residence time equals one, which is the natural decay constant of the cell.", "Where the holdup reaches the declared swarm limit, since that is where the removal curve is pinned.", "Where the bubble rise velocity equals the superficial gas velocity, so the swarm is neither accumulating nor thinning.", "Where the rate multiplied by the residence time equals the log of two, because an exponential has used up half of what it started with there."]'::jsonb, 3, 'On the KOKORI cells the residence is 434.751720 s and the cut comes out at 23.734355 micron. Both interception devices in this module define their cut that way, which is why the same log of two appears in the bed as well.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 10, 'The published pair that straddles the flotation residence threshold differs in the CELL VOLUME alone. What does the module report on each row?', '["6.1 m3 gives 61.000000 s with a warning and 5.9 m3 gives a refusal.", "6.1 m3 gives 61.000000 s and no warning, and 5.9 m3 gives 59.000000 s and a warning.", "Both rows warn, because the holdup on each of them is past the declared swarm limit as well.", "6.1 m3 gives 61.000000 s and 5.9 m3 gives 59.000000 s, and neither row carries any warning at all."]'::jsonb, 1, 'Two seconds of residence either side of the threshold is the whole difference between those rows, and the holdup is under the swarm limit on both, so this warning is shown on its own rather than tangled with the other one.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 11, 'Both rows of that straddling pair report a cut size of 74.465948 micron. Why is the cut the same number on both?', '["Because a smaller cell is a shorter residence and a higher gas flux at once, and the cell volume cancels out of the product the cut is defined by.", "Because the cut was computed at the threshold volume and carried across to both rows for comparison.", "Because the module holds the cut size fixed whenever it warns, so the warning can be read on its own.", "Because the two cells differ by too little volume for the difference to show at six decimals."]'::jsonb, 0, 'The rate carries the flux and the cut is the droplet for which the rate times the residence is the log of two. So the warning is a statement about the CELL and about how little time the attachment process is being given, and the cut size beside it will not show it.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 12, 'The module declares `flotationResidenceWarnS` at 60 s. How does the warning use that figure?', '["It withholds the cut size whenever the residence falls under it, and reports the concentration alone.", "It scales the cut size by the ratio of the residence to the threshold whenever the residence is short.", "It quotes the threshold it judged against in the warning text, so a reader can disagree with the threshold itself.", "It refuses below it, because the attachment kinetics have no meaning at a residence that short."]'::jsonb, 2, 'In the engine''s own words: 59.0 s of flotation residence is under the 60 s this module warns below: the attachment process needs time and this cell is too small for the flow. The KOKORI cells sit at 434.751720 s, far above it.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 13, 'The bubble is changed from 300 micron to 1200 micron. What does the cut size do?', '["It becomes four times coarser, because the cut goes linearly with the bubble diameter.", "It becomes 8.000000 times finer, because a larger bubble sweeps more water on its way up.", "It does not move, because the gas rate rather than the bubble size is what sets the interception rate.", "It becomes 8.000000 times coarser, because the cut goes as the bubble diameter to the three halves."]'::jsonb, 3, 'The rate carries the inverse cube of the bubble diameter and the cut is a square root of a rate. FINER BUBBLES CUT FINER, and that is the larger of the two engineering differences between the two kinds of cell.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 14, 'Which of these does the module REFUSE outright?', '["A gas to water volume ratio of 4, because it holds that ratio to 3.", "A gas to water volume ratio of 1.5, because the holdup it produces is past the swarm limit.", "A bubble of 40 micron, because the attachment model is stated from 300 micron upward.", "A cell depth of 6 m, because the plan area it leaves is too small for the gas to disengage."]'::jsonb, 0, 'A 5 micron bubble is refused too, because the diameter must lie between 20 and 2000 micron for this attachment model. A refusal names the input it was handed and reports nothing else, where a warning reports an answer and says something about it.'),
  ('producedwater', 'intermediate', 'module', 'm04-flotation', 15, 'The gas to water ratio is raised from 0.02 to 0.25 at a fixed bubble. Which way does the cut go?', '["Coarser, from 23.734355 micron to 83.913617 micron, because more gas is a shorter contact per bubble.", "Finer at first and then coarser, turning over once the holdup passes the declared 0.2.", "The cut falls, 83.913617 micron at the low gas ratio against 23.734355 at the high one.", "It holds, because the gas ratio reaches the cut only through the holdup and the holdup is reported separately."]'::jsonb, 2, 'More gas is a higher superficial velocity through the same plan area, so the rate rises and the droplet the cell can remove half of gets smaller. The holdup rises with it, which is what the swarm limit is watching.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 1, 'How does a media bed remove droplets far smaller than the gaps between its grains?', '["By screening the droplets out at the face of the bed, where the packing is at its tightest and the pore throats are at their narrowest.", "By DEPTH FILTRATION: droplets come close to grain surfaces throughout the bed, touch them and are retained.", "By coalescing the droplets on the media surfaces until they are large enough to rise out of the water standing above the bed.", "By holding the water still long enough inside the pores for the droplets to settle out under gravity."]'::jsonb, 1, 'Capture happens everywhere in the bed rather than on its face, which is why the right way to describe it is a rate per unit of depth and why a bed can hold a great deal of oil before anything is visible at the surface.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 2, 'Which three quantities move the filter coefficient in this module?', '["The droplet diameter, the bed depth and the loading rate, each through its own declared exponent.", "The grain size, the bed depth and the bed area, which together fix how much surface the water sees.", "The droplet diameter, the grain size and the bed depth, with the loading rate entering the cut alone.", "The droplet diameter through its square, the grain size through its inverse cube, and the loading rate through a falling power."]'::jsonb, 3, 'Interception is behind two of them. A bigger droplet reaches a grain from further away, and finer grains mean both more collectors per unit volume and a better interception efficiency on each one.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 3, 'A 20 m2 bed 0.8 m deep on 650 micron media carries the KOKORI flow. What does the module report?', '["A loading of 24.841765 m/hr, a filter coefficient of 3.5 per m, and a cut of 12.492787 micron.", "A loading of 62.104412 m/hr, a filter coefficient of 2.618404314893 per m, and a cut of 11.504808 micron.", "A loading of 24.841765 m/hr, a filter coefficient of 4.140060735138 per m, and a cut of 9.149437 micron.", "A loading of 1.013950 m/hr, a filter coefficient of 20.492255142381 per m, and a cut of 4.112471 micron."]'::jsonb, 2, 'The penetration at the reference droplet on that bed is 0.036441443726, so 96.355856 percent of the droplets at that ONE size are caught. The cut size is the separate figure the train reads.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 4, 'Why can the 96.355856 percent that bed reports not be quoted as what it does to produced water?', '["Because it is the removal at ONE droplet size, the 20 micron reference, and real water carries most of its oil volume at other sizes.", "Because it was computed at the reference grain rather than at the 650 micron media the bed actually holds.", "Because it is the penetration rather than the removal, so the figure a reader wants is its complement.", "Because it holds only while the bed is clean, and the module carries no fouling or breakthrough over time."]'::jsonb, 0, 'The bed treats every droplet size differently, which is the whole content of a depth filtration model. What the train reports is that same curve integrated over the distribution in front of the bed.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 5, 'The cut size of this bed is described as an inversion rather than a second opinion. What does that mean?', '["The cut is computed from the grade curve of the declared sharpness and then checked against the penetration law.", "The cut is found by marching the bed layer by layer until the marched removal reaches one half.", "The cut is read from the published bed rows nearest the loading the caller supplied.", "There is exactly one droplet for which the filter coefficient times the depth is the log of two, and the module reports that droplet."]'::jsonb, 3, 'Nothing new is assumed to get it. One law, read two ways, with no second parameter set anywhere, which is why a reader who understands the exponential understands everything this device does.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 6, 'The depth sweep carries a derived column, the cut size times the square root of the depth. What does that column do and what does it prove?', '["It rises with the depth, which says the depth is a stronger lever than the square root would suggest.", "It reads 8.183505 on every row, which says the cut goes as one over the root of the depth exactly.", "It reads 4.140060735138 on every row, which is the filter coefficient the whole sweep was run at.", "It falls with the depth, which says the bed loses capture per unit depth as it is made deeper."]'::jsonb, 1, 'A swept table with a derived column that holds still is a claim about the FORM of a relationship, testable by eye, and it cannot be produced by accident. Across that sweep the depth moves the cut by a factor of 10.000000.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 7, 'Why does the filter coefficient column hold at 4.140060735138 per m all the way down the depth sweep?', '["Because depth is not one of the three things the filter coefficient depends on.", "Because the sweep ran at the reference loading.", "Because the module recomputes the coefficient only when the media or the bed area changes.", "Because the coefficient is DECLARED and the module never scales it away from its declared value."]'::jsonb, 0, 'Depth enters through the exponential rather than through the rate per unit depth. The two columns doing the work in that table are the one that holds still and the one derived beside it.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 8, 'Changing the media from 800 micron to 400 micron multiplies the filter coefficient by 8.000000. Why that factor?', '["Because the coefficient carries the inverse square of the grain diameter and a bed of that media holds twice as many grains in it.", "Because the reference coefficient is declared at 800 micron and the module doubles it per halving.", "Because the interception derivation gives the inverse CUBE of the grain diameter, and halving it cubes to eight.", "Because the grain enters through the loading rate, which falls as the grain size to the power 0.5."]'::jsonb, 2, 'Two separate effects multiply together. Finer grains mean MORE collectors in a given volume of bed, and finer grains also make each collector better at interception.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 9, 'What is the standing of that grain size exponent?', '["DERIVED, because it follows from the same interception argument that fixes this device''s sharpness at 2.", "HELD FOR LITERATURE, because the interception derivation gives the cube and this repository carries no bed data to check it against.", "DECLARED, because it lives in the frozen constants beside the reference grain of 800 micron.", "A CALIBRATION, because it was chosen so that a walnut shell bed cuts where such beds are customarily credited."]'::jsonb, 1, 'It is a very strong dependence on an input a reader is free to change, so the grain column should be read as the MODEL''S STATEMENT. No gate here validates it, because there is nothing here to validate it with, and no citation may be invented for it.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 10, 'At the module''s own reference grain the derived ratio column reads exactly 1.000000. Why is that worth knowing?', '["Because the bed cut size is at its finest there, which is why the reference was chosen at that grain.", "Because it is the only grain at which the module will report a cut size without a warning attached.", "Because the exponent is validated at that grain, and the ratio column is what records the validation.", "Because a bed packed at 800 micron gives an answer the held exponent is doing nothing to."]'::jsonb, 3, 'That is a reasonable thing to know when you want a result that does not rest on a number nobody here can check. Work away from it and the held cube is carrying part of your answer.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 11, 'By what single route does the AREA of a bed reach its cut size?', '["Through the loading rate, the flow divided by the area, and through nothing else at all.", "Through the filter coefficient directly, which carries the bed area beside the grain size and the droplet.", "Through the exponential, since the penetration is taken over the area as well as over the depth.", "Through the residence time of the water in the bed, which the loading rate is another form of."]'::jsonb, 0, 'The area is not in the exponential, it is not in the depth and it is not in the grain term. A bigger bed at the same flow is a slower bed, water spends longer near the grains, and the coefficient rises: 80 m2 gives 6.210441 m/hr and a cut of 6.469629 micron.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 12, 'An 8 m2 bed on this flow runs at 62.104412 m/hr and the module warns. What does the warning do to the answer?', '["It withholds the cut size altogether, because depth capture is not defined anywhere above the declared breakthrough loading.", "It scales the cut size by the ratio of the loading to the 25 m/hr threshold before reporting it.", "Nothing. The cut of 11.504808 micron is still reported, with a statement that the bed will break through early.", "It reports instead the cut size the bed would have given at the threshold, so that the figure stays inside the declared band."]'::jsonb, 2, 'A warning reports an answer and says something about it. Breakthrough is the bed passing oil before it is anywhere near full, and it is a real operating failure rather than a modelling nicety.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 13, 'A 600 m2 bed is put on the KOKORI flow. What does the module do?', '["It warns and reports a cut size, because a slow bed is the conservative direction to be wrong in.", "It answers without comment, since the breakthrough warning is the only thing the loading rate triggers.", "It clamps the loading at the 10 m/hr the coefficient is declared at and reports the cut that gives.", "It REFUSES, because the loading of 0.828 m/hr is below the 1 m/hr floor it answers above."]'::jsonb, 3, 'The reason is on the refusal rather than in a range check. The filter coefficient is DECLARED at 10 m/hr and its loading exponent is the only velocity dependence in this model, so below the floor the declared law is already claiming several times the one coefficient there is any calibration for.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 14, 'That refusal names the bed that would run this flow AT the floor. What is that figure and where does it come from?', '["496.835297 m2, which the return carries as `areaAtFloorM2` against the 20 m2 bed this stream actually runs.", "496.835297 m2, which is the reference bed area the filter coefficient of 3.5 per m is declared at.", "490 m2, which is the smallest bed on this flow that the module refuses to answer for.", "2000 m2, which is the second of the two beds the section refuses and the one sitting furthest under the floor."]'::jsonb, 0, 'The answering beds the section walks on this flow are 200, 400 and 490 m2, cutting at 5.145107, 4.326502 and 4.112471 micron. The floor area is the quantity the refusal names for a caller who wants to know what to change and by how much.'),
  ('producedwater', 'intermediate', 'module', 'm05-the-bed', 15, 'Why is the loading floor a refusal where the breakthrough loading is only a warning?', '["Because a loading that low would put the cut droplet well outside the creeping flow band that this module states its migration law to.", "Because the loading exponent changes sign below the floor, so the reported cut would be meaningless.", "Because what a bed really does far below its design rate is HELD FOR LITERATURE, so there is no answer to report.", "Because the module refuses wherever a warning would have to quote two thresholds in one sentence."]'::jsonb, 2, 'The refusal names four things and each is doing work: the loading it was given, the floor it is under, the reference loading the coefficient is declared at, and the bed that would reach the floor. This module will not extend a coefficient declared at one loading down past the floor and then report the result as a cut size.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'What separates a dissolved gas cell from an induced gas one in this module?', '["The bubble size and the gas rate, and nothing else about the two boxes differs.", "The residence time and the cell depth, since a dissolved cell holds its water far longer.", "The attachment efficiency and the interception coefficient, which each machine carries its own value of.", "The grade curve sharpness, 2 induced and 3 dissolved."]'::jsonb, 0, 'The presets read 0.2 and 300 micron for the induced cell and 0.03 and 80 micron for the dissolved one. Everything else is the same physics of bubbles rising through water and intercepting oil.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'The two presets report cuts of 17.235518 micron and 6.128184 micron. What do those figures give when divided?', '["That the dissolved cell cuts 2.812500 times finer, and on 2.812500 times the gas.", "That the induced cell cuts 2.812500 times finer, which is what the higher gas rate buys it.", "That the dissolved cell cuts 2.812500 times finer, and on 0.150000 times the gas.", "That the two cells cut within 0.150000 of each other."]'::jsonb, 2, 'Both figures are derived, the pairs on those two rows divided. The finer cut on far less gas is what the interception law makes sense of, since the rate carries the inverse cube of the bubble diameter and carries the gas rate only once.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Why is the comparison between those two presets a test of the MODEL rather than of the menu?', '["Because the presets are the only two arrangements the golden file carries a published row for.", "Because a preset that moved no reported field would be refused by the module rather than answered.", "Because the two rows are the only place the module reports the superficial gas velocity back.", "Because a model in which the bubble size could not move the cut would make the two presets the same device behind two labels."]'::jsonb, 3, 'So a reader handed a studio with two device buttons has a question to ask before trusting either: which inputs differ between them, and does the model use those inputs. If the answer is a label and a different picture, the two buttons are decoration.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'One cell of 60 m3 and twelve cells of 5 m3 are run at equal total volume and equal total gas. What does the module report for the cut size?', '["48.447550 micron for the single cell and a finer cut for the twelve, which is what staging buys.", "48.447550 micron on both, and on the two arrangements in between as well.", "A cut size that falls steadily as the bank is split into more cells, since each one is fed its own share of the gas.", "A cut size that rises as the bank is split into more cells, since splitting the volume shortens the residence in each."]'::jsonb, 1, 'The spread across the four arrangements is 7.11e-15 micron, which is derived, the largest minus the smallest, and it is machine noise. A jest test asserts the invariance to 1e-12.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Why did the gas ratio have to be scaled by the cell count for that comparison to mean anything?', '["Because the module refuses a gas ratio above 3 and twelve cells at the single cell ratio would exceed it.", "Because the residence time is computed per cell, so the ratio has to be divided to keep it constant.", "Because the ratio is applied to EACH cell, so holding it fixed would feed twelve cells twelve times the gas.", "Because the plan area of each cell falls with the cell count, and the gas flux would otherwise have to be reported per bank instead."]'::jsonb, 2, 'Two things had to be held: the total volume, so the water spends the same time in the bank, and the total gas, so the bank is fed the same gas whichever arrangement it is in.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'What WOULD have been wrong if the cut size had moved across those four arrangements?', '["The model would have picked up a dependence on how a user chose to describe the same equipment.", "The model would have been reporting the gas per cell where it should report the bank total.", "The model would have been using a residence time that carries the cell count as well as the volume.", "The model would have been refusing an arrangement it should have answered, which is the harder defect."]'::jsonb, 0, 'That is a defect rather than a feature, and it is nearly impossible to spot from a single run because there is no obvious wrong answer to look for. The only way it shows up is by asking the model the same question twice in two forms.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Does the cell count ever move the answer in this module?', '["No, because the chain is built from the total volume and the total flow and never from the count.", "Yes, but only past twelve cells, where the residence in each one falls under the declared threshold.", "No, and the module reports the count back purely so that a reader can check the arrangement.", "Yes, when the gas RATIO is held instead of the total gas, because four cells at a ratio use four times the gas of one."]'::jsonb, 3, 'The return reports the gas per cell AND the total on every call, so that reason is on the screen rather than left to be inferred. A reader comparing two arrangements can see at once whether they were fed the same gas.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The KOKORI train puts three unlike devices in series. Which argument produced which cut size?', '["A field and a travel gives 9.149437 micron, a collision rate against a residence gives 4.430689, and an exponential through a depth gives 23.734355.", "A field and a travel gives 4.430689 micron, a collision rate against a residence gives 23.734355, and an exponential through a depth gives 9.149437.", "A surface loading inverted gives 4.430689 micron, an exponential through a depth gives 23.734355, and a collision rate gives 9.149437.", "All three come from the same inverted settling balance, applied at three different effective areas."]'::jsonb, 1, 'Three numbers of the same kind, produced by three arguments with almost nothing in common. A reader who can say which argument produced which number, and which input each one responds to, has finished the tier.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'On that train the flotation stage has the coarsest cut of the three and removes 11.678001 percent. What is the right reading of that figure?', '["That the water reaching it had a median of 6.843000 micron, because the liner bank had already taken the coarse oil out.", "That the cell is undersized for this flow, since it is the only one of the three stages that carries a residence time at all.", "That the cell is a weaker device than the bed, which removes 36.459384 percent from the same water.", "That a coarse cut size is always worth less in a train, whatever position the device is put in."]'::jsonb, 0, 'A device removes the droplets it is good at, so the next device faces finer water than the inlet did and performs worse on it than its own cut size suggests. Judging one stage without knowing what reached it is the mistake this table exists to prevent.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What does that three stage train leave, on 900 ppm at d50 20 micron and sigma 0.7?', '["45.869949 ppm, 94.903339 percent removed, and a droplet median of 6.843000 micron.", "40.513256 ppm at 11.678001 percent removed, with a median of 6.471437 micron, which is what the middle stage of that train reports.", "25.742373 ppm, 97.139736 percent removed, and a droplet median of 5.557324 micron.", "25.742373 ppm at 36.459384 percent removed."]'::jsonb, 2, 'The overall removal is over every stage in the train rather than any one of them, and the median falls from 20.000000 micron at the inlet. The two distractor pairs above are stage figures read as though they were the train''s.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Five IDENTICAL devices, each cutting at 9 micron, are put in series on one water. What does the removal column do?', '["It holds at 65.398946 percent on every stage, because the devices are identical and the water is the same.", "It falls from 65.398946 percent at the first stage to 12.284239 percent at the fifth.", "It rises from 12.284239 percent to 65.398946 percent, because each stage faces a cleaner and easier feed.", "It falls to zero by the third stage, since a device cannot remove oil finer than its own cut size."]'::jsonb, 1, 'If a device were a fixed efficiency every row would be the same number. The fifth removes what it does because the water reaching it has had its coarse oil taken out four times already.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Compounding that first stage removal five times over predicts an outlet of 8.927280 ppm. What does the train actually report?', '["250.692079 ppm, because the binned quadrature loses its accuracy once the surviving volume has fallen below the module reporting floor.", "8.927280 ppm, which is what makes the compounding a fair shortcut for a train of identical devices.", "250.692079 ppm, because the module applies a declared coupling penalty at each stage after the first.", "250.692079 ppm, because the later stages face water the earlier ones have already stripped of its coarse oil."]'::jsonb, 3, 'The compounded figure is derived, the first stage removal raised to the fifth. The gap between the two is the entire case against reading a train as a chain of fixed efficiencies.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The four stages of a train are reversed. What moves and what does not?', '["Every stage removal moves and the train outlet and the outlet median do not.", "Every stage removal moves and so does the train outlet, because the coupling is order dependent.", "Nothing moves at all, because a train is a product of survivals and the order of the stages is arbitrary.", "The train outlet moves and the stage removals do not, because each device keeps its own grade curve."]'::jsonb, 0, 'A device removes a fixed FRACTION of each droplet size, so the volume surviving in any one size bin is the PRODUCT of the survivals across the devices, and a product does not care what order it is taken in.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'By how much do the per stage removals move when that train is reversed, and what should a reader conclude?', '["By as much as 57.344778 percentage points, which is why the module reports the stages in a fixed order.", "By less than the six decimals the removals are printed to, which is what makes the identity checkable.", "By as much as 57.344778 percentage points, so two trains must be compared on their OUTLETS.", "By an amount that depends on the inlet distribution, so no general figure can be quoted for it."]'::jsonb, 2, 'The outlet concentration agrees to 7.09e-16 relative both ways, which is float rounding. A reader judging one stage must know what reached it, and a reader comparing two trains must look at what came out.'),
  ('producedwater', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What engineering question does that order identity NOT answer?', '["Whether the reversed train leaves the same outlet concentration, which is the quantity the identity is stated on.", "Whether the per stage removals change when the order does, which the reversed table prints in full.", "Whether the outlet droplet median depends on the order the devices were placed in.", "Why a designer still puts the coarse device first, which is decided by fouling, plugging and how much oil each device can take in its reject."]'::jsonb, 3, 'This module carries none of those three. An invariance in a model is a statement about the model, and reading it as a statement about a plant is how a correct identity becomes a wrong design.'),
  ('producedwater', 'intermediate', 'final', null, 1, 'Applying a device to a water produces two separate results in this module. What are they?', '["The removal, which is the grade curve integrated against the inlet distribution, and the outlet distribution, which is what survived it renormalised.", "The cut size, which the geometry produces, and the removal, which the grade curve produces from it.", "The removal and the Reynolds number of the cut droplet, which together say whether the answer is honest.", "The outlet concentration and the outlet median, which the module reports in place of any removal at all."]'::jsonb, 0, 'The second one is the one a reader forgets, and it is what makes a train behave the way a train behaves. Without it a device could not be put in front of another device at all.'),
  ('producedwater', 'intermediate', 'final', null, 2, 'At a reduced size of 0.5 the sharpness of 2 gives 0.200000000000 and the sharpness of 3 gives 0.111111111111. What has happened between the two columns?', '["The sharper curve has moved its half point above a reduced size of one, which is what sharpening means.", "The two curves have crossed, which they do once on each side of the cut size in this family.", "The sharper curve has fallen further below the half point, because it separates more decisively either side of the cut.", "The sharper curve has lost removal it makes up nowhere, since both curves pass through the same points."]'::jsonb, 2, 'Half of the cut size is below the cut, so this is the fine side. The same pair of columns at twice the cut size runs the other way, 0.888888888889 against 0.800000000000.'),
  ('producedwater', 'intermediate', 'final', null, 3, 'A device on this water reports a removal of 44.236922 percent. Which cut size was it given?', '["20 micron, and the outlet median on that row is 14.126621 micron.", "30 micron, and the outlet median on that row is 16.943389 micron.", "6 micron, and the outlet median on that row is 7.691060 micron.", "30 micron, and the outlet median stays at the inlet median because so little was removed."]'::jsonb, 1, 'It is the coarsest cut in that sweep and the smallest removal in it. Even there the outlet median has moved, because the device took coarse oil preferentially however little of it there was.'),
  ('producedwater', 'intermediate', 'final', null, 4, 'Place the sharpness of 2 in the four kinds of number this module deals in.', '["DECLARED, because it sits in the same frozen object as the sharpness of 3 and was chosen the same way.", "A CALIBRATION, because it was set so that a bed and a cell cut where such devices are customarily credited.", "HELD FOR LITERATURE, because no published grade curve for a flotation cell exists in this repository.", "DERIVED, because it follows from interception capture and there is nothing left to check once that is said."]'::jsonb, 3, 'A reader who can place a figure in the right one of the four kinds has the most useful thing this course teaches. The sharpness of 3 beside it in the same column of the same table is DECLARED.'),
  ('producedwater', 'intermediate', 'final', null, 5, 'A device return carries `outletNormalised` as no. What does that tell a reader?', '["That the caller supplied bins without edges, so the module could not place a median inside them.", "That the outlet is reported on the inlet grid rather than on a grid renormalised to the survivors.", "That the surviving volume was too small to describe as a distribution, so no outlet droplet median comes back.", "That the device removed nothing measurable, so the outlet and the inlet distributions are the same."]'::jsonb, 2, 'The concentration still comes back. The shape of what is left does not, because renormalising a volume of the order of 9.618e-13 produces a median with a confident look and no content.'),
  ('producedwater', 'intermediate', 'final', null, 6, 'The published train rows are written by an oracle that fires 400000 droplets through every stage with no binning anywhere. Why does that matter to this tier?', '["Because it checks the binned quadrature under every removal figure by a route that has no bins in it.", "Because it produces the cut sizes the engine reports, so the engine is a lookup over the oracle''s results.", "Because it is the only route by which the outlet droplet median can be computed at all.", "Because it fixes the bin count and the span the module then reports back on every return."]'::jsonb, 0, 'Each droplet carries its own surviving weight through every stage. An agreement between two routes that share no arithmetic is worth something, where an agreement between two copies of one routine is worth nothing.'),
  ('producedwater', 'intermediate', 'final', null, 7, 'Which liner inputs reach the FIELD, and which reach the TRAVEL?', '["The field is reached by the bore and the turndown, and the travel by the core position alone.", "The field is reached by the turndown alone, and the travel by the bore and the declared core position.", "The field is reached by the bore and the length of the liner, and the travel by the turndown together with the core position.", "Both are reached by all four, which is why a liner count moves every term in the answer at once."]'::jsonb, 1, 'Separating the two is what makes the bore sweep readable. Nothing about the shape of the tube enters the field, so widening it is a race between the residence time and the distance and nothing else.'),
  ('producedwater', 'intermediate', 'final', null, 8, 'The KOKORI liner residence of 0.975987 s is a ratio of which two quantities?', '["The liner length and the axial velocity down the tube.", "The travel to the core and the migration velocity at the cut.", "The bank volume and the flow arriving at the whole vessel.", "The liner volume and the flow through that one liner."]'::jsonb, 3, 'It is the simplest quantity in the module and nothing else enters it. The travel over the migration velocity happens to give the same number, and that identity is how the cut was found rather than how the residence was.'),
  ('producedwater', 'intermediate', 'final', null, 9, 'Two liners differ only in bore, one at 0.02 m and one at 0.06 m, at the same length and the same flow each. Which cuts finer?', '["The 0.02 m bore, at 3.383995 micron, because the droplet has less distance to cross.", "Neither, because the bore reaches the answer only through the field and the field has not moved.", "The 0.06 m bore, at 3.383995 micron against 5.861251 micron.", "The 0.02 m bore, because the travel falls linearly while the residence falls only as a square root."]'::jsonb, 2, 'Count the powers rather than arguing from the picture. Volume goes with the square of a diameter and a radial gap goes with the first power, so the wider tube is ahead by one and the answer is settled at every bore rather than only at these two.'),
  ('producedwater', 'intermediate', 'final', null, 10, 'What does the constant 0.828906 column beside the bore sweep establish?', '["That the exponent relating the cut to the bore is exactly one half, so the direction can never turn over.", "That the five rows of the sweep were all computed at one single turndown, which is what holds the field column still across them.", "That the module''s declared bore of 0.035 m is the optimum, since the column is normalised there.", "That the cut and the bore are inversely proportional to one another, so that doubling the bore of a liner would halve the cut size it reports."]'::jsonb, 0, 'An exact exponent is a much stronger thing to know than a trend across five sampled points. It rules out every bore the sweep did not visit, which no amount of extra rows could do on its own.'),
  ('producedwater', 'intermediate', 'final', null, 11, 'Why does no bore in that sweep change the reported field of 1322.687929 g?', '["Because the sweep was run at the ceiling, where the field is held whatever else moves.", "Because the bore enters the tangential velocity and enters the radius as well, in a way that cancels the two contributions exactly.", "Because the field is DECLARED at exactly that value for the KOKORI bank, and the module does not recompute it from row to row of a sweep.", "Because the field follows the turndown, which is a flow divided by a flow and carries no length at all."]'::jsonb, 3, 'That is what makes the bore sweep a clean experiment. One column is held by construction rather than by coincidence, so the movement in the cut column has only two possible sources.'),
  ('producedwater', 'intermediate', 'final', null, 12, 'Which end of the cut droplet''s radial journey is a DECLARED choice with no published source here, and what does typing 0.2 there do?', '["The half-area radius, and at 0.2 the travel becomes 0.008874368671 m and the cut becomes 2.326580 micron.", "The oil core position, and at 0.2 the travel becomes 0.008874368671 m and the cut becomes 6.933042 micron.", "The oil core position, and at 0.2 the module refuses, because the core must lie inside the half-area radius.", "The half-area radius, and at 0.2 nothing moves at all, since that radius is derived rather than stored."]'::jsonb, 1, 'Pulling the core in towards the axis lengthens the gap the median droplet has to make in the same residence time, so the liner appears to catch coarser oil. A reader moving that input is moving a modelling assumption about where oil gathers in a spinning tube.'),
  ('producedwater', 'intermediate', 'final', null, 13, 'The half-area radius is described as a criterion rather than a constant. What is the difference?', '["It is checked against the published rows rather than declared, which is what makes it a criterion.", "It is the value a caller may override, where a constant is frozen in the exported object.", "It is where the median droplet is by construction, so the module derives it rather than storing it as a choice.", "It is stated to a band rather than to a value, which is why the refusal quotes 0.7071 rather than an exact figure."]'::jsonb, 2, 'Equal areas of the inlet carry equal volumes of water and so equal volumes of oil. That fixes the starting radius of the median droplet at one over the root of two whatever else about the liner changes.'),
  ('producedwater', 'intermediate', 'final', null, 14, 'The KOKORI bank of 200 liners runs at a turndown of 1.150082. Where in the operating envelope does that sit?', '["Above the design point and below the top of the envelope, so no penalty and no warning apply.", "Above the top of the operating envelope, which is why the reported field has already reached its ceiling there.", "Below the starved edge of the envelope, which is why the module advises shutting liners in on a bank like that one.", "Exactly at the design point, which is what a turndown a hair above one is defined to mean for a bank of this kind."]'::jsonb, 0, 'The declared edges are 0.5 at the bottom, 1.3 at the top and 2 past which the module stops answering. Inside that band the field rises as the square of the turndown and the reported cut is the ideal cut.'),
  ('producedwater', 'intermediate', 'final', null, 15, 'Going from 230 liners to 177 on the KOKORI flow, what does the field column do?', '["It rises from 1000.142101 g to 1690.000000 g, which is where the ceiling caught it.", "It falls from 1688.771335 g to 1000.142101 g, because fewer liners is less total energy into the swirl.", "It rises from 1000.142101 g to 1688.771335 g, still under the ceiling.", "It holds, because the field is fixed by the declared 1000 g at the design flow of one liner."]'::jsonb, 2, 'Fewer liners means each one carries more flow, and the field goes as the square of that. The 177 liner row is the last one under the ceiling and it carries the finest cut in the sweep.'),
  ('producedwater', 'intermediate', 'final', null, 16, 'At 150 liners the module reports a shear penalty of 1.086081, an ideal cut of 4.526119 micron and a reported cut of 4.915730 micron. Why are the two cuts kept as separate fields?', '["So that the caller can choose which of the two figures to use, since the module states no preference at all between them.", "So a reader can see how much of the answer is physics and how much is the price of running the bank too hard.", "So the golden file can pin both, which is what lets the jest suite catch a change to either one.", "So the ideal cut can be compared against the oracle, which marches its droplets without any inlet shear in the model at all."]'::jsonb, 1, 'The module did not quietly cap a number and carry on. It kept both figures with the multiplier between them, and the multiplier is the root of the overload because inlet shear breaks droplets finer than they arrived.'),
  ('producedwater', 'intermediate', 'final', null, 17, 'A designer reads the CUT MICRON column of the sweep upward from the smallest bank. What do they see?', '["It improves without any limit at all as more liners are added, which is the reason the printed table has to stop somewhere.", "It worsens the whole way, which is the argument for buying the smallest bank that answers.", "It improves to the design point at 230 liners and holds flat above it.", "It improves as liners are added up to 177 and then begins to worsen again towards the starved end."]'::jsonb, 3, 'Everything above the turning row is the square law on the field. Everything below it is the ceiling together with the inlet shear penalty. A designer who stopped at any one row would have met only one of those two regimes.'),
  ('producedwater', 'intermediate', 'final', null, 18, 'Which of these does the 115 liner refusal NOT put in its sentence?', '["The cut size the bank would have reported if the module had been willing to answer.", "The flow each of those liners is carrying and the multiple of design flow it represents.", "The declared design flow per liner that the figure was judged against.", "The liner count that would run this flow at its design point."]'::jsonb, 0, 'It also says why the limit is there: past twice design the pressure drop and the inlet shear decide the answer and this model does not carry them. A refusal that names what to change is worth more than a bare error.'),
  ('producedwater', 'intermediate', 'final', null, 19, 'Why does 0.500455 appear on every row of the published cyclone group rather than a different figure per row?', '["Because the oracle was run once at the declared bore and its result was recorded onto every row of the group.", "Because the golden file stores the engine''s own capture fraction, which the module holds fixed by construction.", "Because each row is marched at its OWN reported cut size, and a cut size is defined as the droplet half of which is captured.", "Because every row in that group happens to sit at the same turndown, so the capture works out the same way."]'::jsonb, 2, 'The oracle fires droplets of that diameter from starting radii spread by area, marches each one and counts how many reach the core. The same figure recurring is the definition holding across five different banks rather than one number copied.'),
  ('producedwater', 'intermediate', 'final', null, 20, 'What general habit does this module''s sweep teach about any model?', '["Check the declared constants first, because a model with no declared constants has nothing to argue with.", "Push the input a user is most tempted to change and check whether the answer has a limit in it.", "Run the published cases first, since a model that reproduces its goldens has no room left for a defect.", "Trust an optimum a model reports whenever the rows either side of it carry warnings."]'::jsonb, 1, 'The habit is portable and needs neither produced water nor this engine. Hand it any model with a result and an input a user will reach for, push that input across the range somebody could plausibly type, and watch the direction.'),
  ('producedwater', 'intermediate', 'final', null, 21, 'What is the superficial gas velocity of a flotation cell, and over which area is it taken?', '["The total gas fed to the bank divided by the plan area of the whole bank of cells.", "The gas rate fed to that cell divided by the cross section a single rising bubble presents to the water around it.", "The bubble rise velocity multiplied by the gas holdup of the swarm, which is the flux that swarm carries upward.", "The gas rate fed to that cell divided by its plan area, which is the cell volume over the cell depth."]'::jsonb, 3, 'On the KOKORI cell the gas per cell is 0.034502451156 m3/s and the plan area is 4.285714 m2, which gives 0.008050571936 m/s. That flux is what the rest of the chain runs on.'),
  ('producedwater', 'intermediate', 'final', null, 22, 'A 40 micron bubble in this water reports a holdup of 5.099128681105. What does the module do with a figure like that?', '["It reports the cut size and warns, because the holdup is far past the declared swarm limit.", "It refuses, because a holdup above one describes a cell with more gas in it than volume.", "It clamps the holdup at the declared 0.2 and reports the cut that the clamped value gives.", "It reports the cut with no comment, because the swarm limit applies to the gas ratio rather than the holdup."]'::jsonb, 0, 'Every number in this chain assumes bubbles that rise on their own, sweep their own volume of water and carry their own interception efficiency. Pack enough gas in and they merge, they rise faster and they sweep differently.'),
  ('producedwater', 'intermediate', 'final', null, 23, 'The cut at a 150 micron bubble is 5.450349 micron and at 300 micron it is 15.415916. What is the ratio of 0.353553 between them?', '["One over two squared, which is how the interception efficiency carries the bubble diameter.", "The square root of the holdup ratio between the two rows, which is what the cut is proportional to.", "One over two to the three halves, which is the law the cut follows in the bubble diameter.", "The ratio of the two superficial gas velocities, which the bubble size does not change."]'::jsonb, 2, 'Take the cube out of the rate, take a square root because the cut is one, and the exponent left over is three halves. The 1200 micron row against the 300 micron row is the same statement at a factor of four, where the column reads 8.000000.'),
  ('producedwater', 'intermediate', 'final', null, 24, 'The 40 micron bubble rises at a Reynolds number of 0.118487. What does that say about the settling law for it?', '["That this bubble is outside the band, since the module states the law to a Reynolds number of 0.1.", "That this bubble is inside the creeping flow band the module states Stokes to, unlike the 300 micron induced gas bubble.", "That the module will report no rise velocity for it, because it is below the bubble diameter band.", "That the full drag balance and Stokes disagree most sharply here, which is why the band is policed."]'::jsonb, 1, 'The Reynolds number climbs much faster than the bubble diameter does, because it carries both the size and the velocity the size produced. The induced gas preset bubble of 300 micron sits at 22.678201, far outside that band.'),
  ('producedwater', 'intermediate', 'final', null, 25, 'The published pair straddling the residence threshold is run at one flow, one depth, one gas ratio and one bubble size. What is the ONLY thing that differs between the two rows?', '["The cell volume, 6.1 m3 against 5.9 m3.", "The cell depth, which is what turns the volume into the plan area the gas rises through.", "The gas holdup, 0.063497860502 against 0.065650330350, which is what the warning is judged on.", "The residence, which is an input to the cell in this module and not a computed quantity."]'::jsonb, 0, 'The holdups on the two rows do differ, but as a consequence of the volume rather than as a separate input, and both sit under the swarm limit so the residence warning is shown on its own.'),
  ('producedwater', 'intermediate', 'final', null, 26, 'Both of those rows report a cut of 74.465948 micron. What would a reader be wrong to conclude?', '["That the cell volume cancels out of the product the cut size is defined by.", "That a smaller cell is a shorter residence and a higher gas flux at the same time.", "That the warning is a statement about the cell rather than about the cut size beside it.", "That the residence warning can be ignored, since the cut size beside it did not move."]'::jsonb, 3, 'The warning says the attachment process is being given too little time in a cell too small for the flow. That the cut size does not show it is the reason the warning has to exist as its own field.'),
  ('producedwater', 'intermediate', 'final', null, 27, 'What standing does `attachmentEfficiency` have in this module?', '["It is DECLARED, in the same frozen object as the interception coefficient and the bubble default.", "It is the one CALIBRATION here, a number with no derivation at all, and it is an input a caller can move.", "It is DERIVED, because the probability a collision sticks follows from the interception geometry.", "It is HELD FOR LITERATURE, so the module states its absence and asks the caller to supply one."]'::jsonb, 1, 'Nothing in this course presents it as published, and no graded answer anywhere in this wave depends on it. A caller with a vendor curve has every right to type their own.'),
  ('producedwater', 'intermediate', 'final', null, 28, 'A caller asks for a 5 micron bubble and the module refuses. What band does the refusal name?', '["40 to 1200 micron, which is the span of the bubble sweep the module publishes.", "80 to 300 micron, which is the range the two cell presets lie between.", "20 to 2000 micron, which is the range this attachment model is stated for.", "It names no band, because the refusal quotes only the value it was given."]'::jsonb, 2, 'A gas to water ratio of 4 is refused the same way, against a ratio the module holds to 3. Each refusal names the input it was handed and the limit it was judged against.'),
  ('producedwater', 'intermediate', 'final', null, 29, 'The KOKORI bed runs at a loading of 24.841765 m/hr. What does the module say about that rate?', '["It warns, because the rate is above the 10 m/hr the filter coefficient is declared at.", "It warns about breakthrough, because 24.841765 m/hr is inside the band the warning covers.", "It refuses, because the loading is more than twice the rate the coefficient has a calibration for.", "Nothing, because it is under the 25 m/hr breakthrough loading the module warns above."]'::jsonb, 3, 'The declared loading rate and the declared breakthrough loading are two different figures doing two different jobs. The first is where the coefficient is quoted and the second is where the module starts warning.'),
  ('producedwater', 'intermediate', 'final', null, 30, 'Quadrupling a bed depth at a fixed area and media moves the cut by what factor, and in which direction?', '["It gets finer, from 12.939258 micron to 6.469629 micron, which is a factor of two on a factor of four in depth.", "It gets finer by a factor of four, matching the factor of four in the depth exactly.", "It gets coarser, because a deeper bed at the same area is a longer contact time and a lower coefficient.", "It does not move, because depth enters the penetration and the module reports the cut at the reference depth."]'::jsonb, 0, 'The derived column that holds still across that sweep is what says the exponent is a half. Nothing about the filter coefficient changes, because depth is not one of the three quantities it depends on.'),
  ('producedwater', 'intermediate', 'final', null, 31, 'At 1200 micron media the filter coefficient is 0.657965381590 per m and the derived column reads 0.296296. What is that column?', '["Each coefficient over the 3.5 per m the reference triple declares.", "Each coefficient over the one at the module''s own 800 micron reference grain.", "Each cut size over the cut size at the reference grain, which runs the other way.", "Each coefficient over the one at the finest grain in the sweep, which is where the column is pinned."]'::jsonb, 1, 'It is the CUBE of the grain ratio, which the 8.000000 row and the 0.125000 row show most plainly. Both the number of collectors per unit volume and the interception efficiency of each one depend on the grain.'),
  ('producedwater', 'intermediate', 'final', null, 32, 'What is the standing of the reference triple, 3.5 per m at a 20 micron droplet, 800 micron media and 10 m/hr?', '["It is DERIVED, because the three reference values follow from the interception law itself.", "It is HELD FOR LITERATURE, which is why the module refuses to answer below the loading floor.", "It is DECLARED, kept in the frozen constants with no published source in this repository.", "It is the one CALIBRATION in this module, which is why no publication stands behind it."]'::jsonb, 2, 'Everything in the loading column is that declared value scaled to a different rate. The one calibration in this module is the attachment efficiency, and a reader arguing with a bed cut size should start with the triple.'),
  ('producedwater', 'intermediate', 'final', null, 33, 'Of the beds the section walks down towards the loading floor, which is the widest that still gets an answer, and what does it report?', '["490 m2, at a loading of 1.013950 m/hr and a cut of 4.112471 micron.", "400 m2, at a loading of 1.242088 m/hr and a cut of 4.326502 micron, with the wider beds all refused.", "600 m2, at a loading of 0.828 m/hr and a cut of 4.112471 micron, which is the last row before the floor.", "496.835297 m2, which is the bed the refusals name, reported at a loading of 1.013950 m/hr."]'::jsonb, 0, 'The three answering beds are 200, 400 and 490 m2, cutting at 5.145107, 4.326502 and 4.112471 micron. The floor under them is a refusal rather than a warning, because what a bed does far below its design rate is HELD FOR LITERATURE.'),
  ('producedwater', 'intermediate', 'final', null, 34, 'A 2000 m2 bed on the same flow is refused. What loading does the refusal quote?', '["0.828 m/hr, which is the loading the 600 m2 bed was refused at.", "1.013950 m/hr, which is the loading of the last bed that answers.", "2.484176 m/hr, which is the loading a 200 m2 bed would be refused at.", "0.248 m/hr, against the 1 m/hr floor this module answers above."]'::jsonb, 3, 'Both refusals carry the same four things: the loading given, the floor, the reference loading the coefficient is declared at, and the bed area that would reach the floor on this flow.'),
  ('producedwater', 'intermediate', 'final', null, 35, 'The loading floor refusal says the declared law is already claiming 3.162 times something at the floor. Times what?', '["The cut size the bed would report at its own reference loading of 10 m/hr.", "The one filter coefficient this module has any calibration for, which is declared at 10 m/hr.", "The breakthrough loading of 25 m/hr, which the floor is stated as a fraction of.", "The penetration at the reference droplet, which is what the exponential is taken over."]'::jsonb, 1, 'The loading exponent of 0.5 is the only velocity dependence in this model, so dropping from 10 m/hr to 1 m/hr multiplies the coefficient by the root of ten. Extending a one point calibration that far and reporting the result as a cut size is what the module declines to do.'),
  ('producedwater', 'intermediate', 'final', null, 36, 'The bed area moves one column of this device and no other. Why is that?', '["Because the module computes the loading rate first and then discards the area it came from.", "Because the area and the depth enter as a product, which the module reports as the bed volume.", "Because the area appears nowhere in the exponential, nowhere in the depth and nowhere in the grain term.", "Because the loading rate is the only quantity in the device that the published rows carry."]'::jsonb, 2, 'So the whole effect of buying a wider vessel arrives through one column, which makes this the cleanest input in the device to reason about and the only one with both a warning and a refusal on it.'),
  ('producedwater', 'intermediate', 'final', null, 37, 'The KOKORI water is 0.000531486500 Pa.s and 997.174641 kg/m3 against 857.655928 kg/m3 of oil. What is the quantity every cut size in that train stands on?', '["The density difference of 139.518714 kg/m3, taken with that viscosity.", "The brine density of 997.174641 kg/m3, which is what the buoyancy is taken against.", "The oil density of 857.655928 kg/m3, which is what fixes the droplet rise in every device.", "The viscosity alone, since the density difference cancels out of a cut size defined at one half."]'::jsonb, 0, 'The figure is derived, the two densities subtracted. That difference and that viscosity are the Associate tier''s half of this course doing its work under every device in the Professional half.'),
  ('producedwater', 'intermediate', 'final', null, 38, 'The hydrocyclone stage of the KOKORI train removes 94.903339 percent and leaves 45.869949 ppm. What does it do to the droplet median?', '["It leaves it at 20.000000 micron, because a removal is a fraction of the oil and does not reshape it.", "It brings it down to 5.557324 micron, which is the median the train reports at its outlet.", "It brings it down to 4.430689 micron, because a stage leaves the water at its own cut size.", "It brings it down from 20.000000 micron to 6.843000 micron, which is the water the next stage sees."]'::jsonb, 3, 'Read the outlet concentration column and the outlet median column together down that table. The concentration is what a downstream process cares about and the median is what the next device cares about.'),
  ('producedwater', 'intermediate', 'final', null, 39, 'The KOKORI train table prints a sharpness of 3 on one row and 2 on the other two. What is the difference in standing between them?', '["The 3 is DERIVED from the settling balance and the 2 is DECLARED for flotation and filtration.", "The 3 is validated against the published cyclone rows and the 2 has no published row anywhere to check it against.", "The 3 is DECLARED for the centrifugal device and the 2 is DERIVED for the two interception devices.", "Both are DECLARED, and the module keeps two values only so that the devices can be told apart."]'::jsonb, 2, 'They sit in the same column and they have completely different standing. One came from a frozen constant somebody chose and pinned, and the other came from the interception law.'),
  ('producedwater', 'intermediate', 'final', null, 40, 'The invariance across one, two, four and twelve cells is stated at equal total volume and equal total gas. Why must BOTH be held?', '["Because the module refuses any arrangement in which the two are not held together.", "Because the residence time is computed from the gas rate as well as from the volume.", "Because the cell count enters the plan area, which carries the volume and the gas equally.", "Because the volume sets the residence and the gas sets the flux, and moving either would make the comparison a different question."]'::jsonb, 3, 'The gas ratio here is applied per cell, so it has to be scaled by the count to keep the total fixed. Hold the ratio instead and the count moves the answer, and it should.'),
  ('producedwater', 'intermediate', 'final', null, 41, 'Five identical devices in series report stage removals whose third row is 20.530945 percent and whose derived column reads 0.313934 there. What is that column?', '["Each stage removal over the first stage''s removal.", "Each stage removal over the removal the whole train reports.", "Each stage outlet over the inlet concentration the train was given.", "Each stage removal over the removal a fixed efficiency device would have given."]'::jsonb, 0, 'The column is derived, each row divided by the topmost one, and by the last row it reads 0.187835. Normalising against the first stage is what turns five raw percentages into a picture of how fast a train runs out of easy oil.'),
  ('producedwater', 'intermediate', 'final', null, 42, 'The OGBOTOBO train is run as designed and then reversed. What does the outlet droplet median do?', '["It moves with the stage order, because the medians are computed stage by stage down the train.", "It is 3.185598 micron as designed and finer reversed, because the coarse device then runs last.", "It is 3.185598 micron both ways, because the survivals in each size bin multiply and a product has no order.", "It cannot be compared, because the reversed train reports its medians against a different grid."]'::jsonb, 2, 'The outlet concentration is 160.391597 ppm both ways as well, agreeing to 7.09e-16 relative. What does move is every per stage removal, by as much as 57.344778 percentage points.');
